/* NECROPOLIS_LANTERN_VIGIL_BEGIN */
// A memory of the village folds into the ordinary first opening of the ossuary.
(() => {
  const chapter = 3;
  const gateCell = "34,21";
  const lineKey = "ossuary_lantern_keeper";
  zb[lineKey] = ["I know that lamp. She walked me home the night we buried my father."];
  const atlasPNG = /* LANTERN_KEEPER_PNG_BEGIN */ "" /* LANTERN_KEEPER_PNG_END */;
  let image = null;
  let vigil = null;

  function warmPortrait() {
    if (image) return;
    image = new Image();
    image.src = "data:image/png;base64," + atlasPNG;
  }

  function portraitTexture() {
    const portrait = Z(e0(() => {}, 400, 288));
    portrait.name = "ossuaryKeeperPortrait";
    portrait.colorSpace = ha;
    portrait.generateMipmaps = false;
    portrait.repeat.set(.25, .5);
    const scene = J.scene;
    function paint() {
      if (scene !== J.scene) return;
      portrait.image.getContext("2d").drawImage(image, 0, 0);
      portrait.needsUpdate = true;
    }
    if (image.complete && image.naturalWidth) paint();
    else image.addEventListener("load", paint, { once: true });
    return portrait;
  }

  function lamplight() {
    const patch = Z(e0((ctx, width, height) => {
      const glow = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, width / 2);
      glow.addColorStop(0, "rgba(255,181,72,.90)");
      glow.addColorStop(.28, "rgba(233,143,47,.66)");
      glow.addColorStop(.65, "rgba(156,82,24,.31)");
      glow.addColorStop(1, "rgba(72,39,17,0)");
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, width, height);
    }, 48, 48));
    patch.colorSpace = ha;
    const material = Z(new $e({ map: patch, transparent: true, blending: is, depthWrite: false, toneMapped: false }));
    // The leading edge folds down the native riser. A horizontal billboard
    // alone nearly disappears at the low viewing angle through this door.
    const strip = Z(new h0());
    strip.setAttribute("position", new y0(new Float32Array(18), 3));
    strip.setAttribute("uv", new y0(new Float32Array(12), 2));
    strip.setIndex([0, 2, 1, 1, 2, 3, 2, 4, 3, 3, 4, 5]);
    const pool = new pt(strip, material);
    pool.name = "ossuaryKeeperTreadLight";
    pool.frustumCulled = false;
    return pool;
  }

  function lightTread(pool, lampX, floor, z) {
    const pos = pool.geometry.getAttribute("position"), uv = pool.geometry.getAttribute("uv");
    const farEdge = Math.floor(z / P) * P, nearEdge = farEdge + P;
    const centerZ = z + .17, reach = 1.28;
    const back = Math.max(farEdge + .004, centerZ - reach);
    const front = Math.min(nearEdge + .008, centerZ + reach);
    const lowerFloor = front > nearEdge ? ie(lampX, nearEdge + .045) : floor;
    const top = floor + .023, low = Math.min(floor, lowerFloor) + .020;
    for (let side = 0; side < 2; side++) {
      const x = lampX + (side - .5) * 2.14;
      pos.setXYZ(side, x, top, back);
      pos.setXYZ(side + 2, x, top, front);
      pos.setXYZ(side + 4, x, low, front);
      uv.setXY(side, side, .5 - (back - centerZ) / (2 * reach));
      uv.setXY(side + 2, side, .5 - (front - centerZ) / (2 * reach));
      uv.setXY(side + 4, side, .5 - (front - centerZ) / (2 * reach) - .30);
    }
    pos.needsUpdate = true;
    uv.needsUpdate = true;
  }

  function begin(gate) {
    const map = portraitTexture();
    const material = Z(new qV({ map, transparent: true, alphaTest: .06, depthWrite: false, toneMapped: false }));
    const keeper = new nh(material);
    keeper.name = "ossuaryLanternKeeper";
    keeper.center.set(.5, 2 / 144);
    const height = 2.05;
    keeper.scale.set(height * 100 / 144, height, 1);
    const pool = lamplight();
    const group = new n0();
    group.name = "ossuaryLanternVigil";
    group.add(keeper, pool);
    J.scene.add(group);
    const x = gate.mesh.position.x, z = gate.mesh.position.z - 3.43;
    vigil = { group, keeper, map, pool, x, z, elapsed: 0, pose: -1, visible: 1,
      withdraw: 0, clinked: false, spoke: false, reduced: matchMedia("(prefers-reduced-motion: reduce)").matches };
  }

  function end() {
    if (!vigil) return;
    vigil.group.removeFromParent();
    vigil = null;
  }

  // Listen to the completed native interaction. A restored/opened door, a
  // locked input, a finisher, and opening from inside do not cue an apparition.
  const interact = N$;
  N$ = function () {
    const gate = T.level === chapter && v.doors[gateCell];
    const closed = gate && !gate.open;
    const result = interact.apply(this, arguments);
    if (closed && gate.open && gate.dir === -1 && !T.key && !vigil) begin(gate);
    return result;
  };

  const load = rp;
  rp = function (level) {
    end();
    const result = load.apply(this, arguments);
    if (level === chapter) warmPortrait();
    return result;
  };

  function setPose(shot, pose) {
    if (shot.pose === pose) return;
    shot.pose = pose;
    shot.map.offset.set((pose % 4) / 4, pose < 4 ? .5 : 0);
  }

  function handleSound(shot) {
    shot.clinked = true;
    Nt(shot.x - .38, ie(shot.x, shot.z) + 1.52, shot.z, () => {
      gt([
        { tone: "sine", f: 624, env: { a: .004, d: .18 }, level: .24 },
        { tone: "sine", f: 1427, env: { a: .002, d: .09 }, level: .11 },
        { at: .053, tone: "sine", f: 913, env: { a: .003, d: .16 }, level: .13 },
      ]);
    });
  }

  const lights = Q$;
  Q$ = function (dt, now) {
    lights.apply(this, arguments);
    const shot = vigil;
    if (!shot) return;
    if (T.dead || T.won || T.level !== chapter) { end(); return; }
    if (Wk() || Qm() || document.hidden || Be.inputLock) return;
    shot.elapsed += dt;
    const t = shot.elapsed;
    const step = Ge(1.76, 2.28, t);
    const pace = Math.max(0, t - 2.08);
    const travel = shot.reduced ? 0 : Math.min(4.1, pace * 1.65) * step;
    const x = shot.x + (shot.reduced ? 0 : .48 * Ge(1.76, 3.26, t));
    const z = shot.z - travel, distance = Math.hypot(C.px - x, C.pz - z);
    // Passing through is always safe. A close or departing player sees the
    // light go out gradually instead of the back of a camera-facing sprite.
    if (shot.withdraw > 0 || distance < 2.8 || C.pz < z || t > 4.35) {
      shot.withdraw = Math.min(1, shot.withdraw + dt * 2.9);
    }
    shot.visible = Math.min(shot.visible, 1 - shot.withdraw);
    const bob = shot.reduced ? 0 : Math.abs(Math.sin(pace * 6.3)) * .025 * step;
    if (shot.visible > 0) {
      const pose = shot.reduced ? 3 : t < .55 ? 0 : t < .71 ? 1 : t < .9 ? 2 : t < 1.76 ? 3 :
        t < 2.01 ? 4 : t < 2.22 ? 5 : t < 2.46 ? 6 : Math.sin(pace * 9) > 0 ? 7 : 6;
      setPose(shot, pose);
      const floor = ie(x, z);
      shot.keeper.position.set(x, floor + bob + .012, z);
      shot.keeper.material.opacity = shot.visible;
      lightTread(shot.pool, x + (pose < 4 ? -.38 : .30), floor, z);
      shot.pool.material.opacity = shot.visible * (shot.reduced ? .85 : (.69 + .22 * Ge(.4, 1.15, t)));
      if (!shot.clinked && t >= .96) handleSound(shot);
    } else shot.group.visible = false;

    // A remark already on screen gets to finish. The memory belongs to this
    // staircase and need not follow a player back across the plaza.
    if (!shot.spoke && t >= 1.06 && distance < 12 && C.pz < 46.8 && !Jt("subt").textContent.trim()) {
      w0(lineKey, true);
      shot.spoke = true;
    }
    if (shot.visible === 0 && (shot.spoke || t >= 7 || distance > 12)) end();
  };
})();
/* NECROPOLIS_LANTERN_VIGIL_END */
